  reg [2:0] last_level;
  reg [1:0] state;
  reg [1:0] next_state;
  wire [1:0] next_level;
  wire [2:0] nominal_fr;
  wire [2:0] supplemental_fr;
  wire [2:0] total_fr;
  reg [2:0] total_fr_reg;
  wire max_fr;
  wire [2:0] fr;
  reg [2:0] fr_reg;
  reg [2:0] fr_next;
  reg [2:0] nominal_fr_reg;
  reg [2:0] nominal_fr_next;
  reg [2:0] supplemental_fr_reg;
  reg [2:0] supplemental_fr_next;
  reg [2:0] total_fr_next;
  reg dfr_reg;
  reg dfr_next;
  wire [2:0] nominal_fr_table [0:7] = '{3'd0, 3'd5, 3'd10, 3'd15, 3'd20, 3'd25, 3'd30, 3'd35};
  wire [2:0] supplemental_fr_table [0:7] = '{3'd5, 3'd10, 3'd15, 3'd20, 3'd25, 3'd30, 3'd35, 3'd40};
  always @(*) begin
    next_level = level + 1'b1;
    if (next_level > 3'd2) next_level = 3'd2;
