// Large reservior of water, flow rate dependent on water level and
// level previous to the last sensor change. One "register" stage is
// used to infer a simple state machine, plus combinational logic to
// compute the flow rate directly from the water level.
module TopModule(input clk, input reset, input [2:0] s, output reg fr2, output reg fr1, output reg fr0, output reg dfr);
    reg [2:0] lvl;
    reg [2:0] lvl2;
    reg [2:0] lvl3;
    reg [1:0] state;
    wire [2:0] sr;
    reg [2:0] fr;
    always @(*) begin
        case (state)
            0: sr = 3'b000;
            1: sr = {1'b0, lvl, 1'b0};
            2: sr = {1'b0, lvl, 1'b1};
            3: sr = {1'b1, lvl, 1'b1};
        endcase
    end
    always @(*) begin
        case ({lvl3, lvl2, lvl})
            3'b000: fr = 3'b000;
            3'b001: fr = 3'b001;
            3'b010: fr = 3'b010;
            3'b011: fr = 3'b011;
            3'b100: fr = 3'b100;
            3'b101: fr = 3'b101;
            3'b110: fr = 3'b110;
            3'b111: fr = 3'b111;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            lvl <= 0; lvl2 <= 0; lvl3 <= 0; state <= 0; fr2 <= 1; fr1 <= 1; fr0 <= 1; dfr <= 1;
        end else begin
            lvl3 <= lvl2; lvl2 <= lvl; lvl <= s;
            case (state)
                0: if (s != 0) state <= 1;
                1: if (s != lvl) state <= 2;
                2: if (s == lvl) state <= 3;
                3: if (s != lvl) state <= 0;
            endcase
        end
    end
    always @(*) begin
        case (sr)
            3'b000: begin fr2 <= 1; fr1 <= 1; fr0 <= 1; dfr <= 1; end
            3'b001: begin fr2 <= 1; fr1 <= 1; fr0 <= 1; dfr <= 0; end
            3'b010: begin fr2 <= 1; fr1 <= 1; fr0 <= 0; dfr <= 1; end
            3'b011: begin fr2 <= 1; fr1 <= 1; fr0 <= 0; dfr <= 0; end
            3'b100: begin fr2 <= 1; fr1 <= 0; fr0 <= 1; dfr <= 1; end
            3'b101: begin fr2 <= 1; fr1 <= 0; fr0 <= 1; dfr <= 0; end
            3'b110: begin fr2 <= 1; fr1 <= 0; fr0 <= 0; dfr <= 1; end
            3'b111: begin fr2 <= 1; fr1 <= 0; fr0 <= 0; dfr <= 0; end
            3'b0001: begin fr2 <= 0; fr1 <= 1; fr0 <= 1; dfr <= 1; end
            3'b0010: begin fr2 <= 0; fr1 <= 1; fr0 <= 1; dfr <= 0; end
            3'b0011: begin fr2 <= 0; fr1 <= 1; fr0 <= 0; dfr <= 1; end
            3'b0100: begin fr2 <= 0; fr1 <= 1; fr0 <= 0; dfr <= 0; end
            3'b0101: begin fr2

