    output reg dfr
);
    reg [1:0] state;
    reg [1:0] next_state;
    reg [2:0] level;
    reg [2:0] next_level;
    reg [1:0] rise;
    reg [1:0] next_rise;
    reg [2:0] fr_level;
    reg [2:0] next_fr_level;
    reg [1:0] fr_time;
    reg [1:0] next_fr_time;
    reg [1:0] dfr_time;
    reg [1:0] next_dfr_time;
