        case (state)
            2'b00: begin
                next_state = 2'b01;
                next_level = level + 1;
                next_rise = rise;
                next_fr_level = fr_level;
                next_fr_time = fr_time;
                next_dfr_time = dfr_time + 1;
            end
            2'b01: begin
                next_state = (s[0]) ? 2'b00 : 2'b10;
                next_level = level + ((s[0]) ? 1 : 0);
                next_rise = (s[0] & ~rise[0]) ? 2'b10 : ((s[0] & rise[0] & level[0]) ? 2'b01 : rise);
                next_fr_level = (next_rise[1]) ? next_level : fr_level;
                next_fr_time = (next_rise[1]) ? 0 : fr_time + 1;
                next_dfr_time = (next_rise[1]) ? dfr_time + 1 : dfr_time;
