// Large reservior of water, flow rate determined by three sensors and a
// state machine to allow smooth transition.
module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);
    reg [2:0] state;
    reg [2:0] next_state;
    reg [2:0] last_state;
    reg [2:0] last_last_state;
    always @(*) begin
        case ({s[2], s[1], s[0]})
            3'b000: next_state = 3'b000;
            3'b001: next_state = 3'b001;
            3'b010: next_state = 3'b001;
            3'b011: next_state = 3'b010;
            3'b100: next_state = 3'b011;
            3'b101: next_state = 3'b011;
            3'b110: next_state = 3'b100;
            default: next_state = 3'b100;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            last_state <= 3'b111;
            last_last_state <= 3'b111;
            fr0 <= 1;
            fr1 <= 1;
            fr2 <= 1;
            dfr <= 1;
        end else begin
            state <= next_state;
            last_last_state <= last_state;
            last_state <= {s[2], s[1], s[0]};
            fr0 <= (state == 3'b000) ? 1 : (state == last_state) ? fr0 : (state < last_state) ? 1 : 0;
            fr1 <= (state == 3'b001) ? 1 : (state == last_state) ? fr1 : (state < last_state) ? 1 : 0;
            fr2 <= (state == 3'b010) ? 1 : (state == last_state) ? fr2 : (state < last_state) ? 1 : 0;
            dfr <= (last_last_state < last_state && last_state < state) ? 1 : 0;
        end
    end
endmodule

