// Large reservoir of water, a flow rate determined by three sensors and a
// state machine. The flow rate increases when the level increases faster
// than when the level decreases. The flow rate is zero when the level is
// above the highest sensor, and the same for the lowest sensor.
module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);
    reg [2:0] last_s;
    reg [2:0] next_s;
    reg [1:0] state;
    reg [1:0] next_state;
    reg [15:0] count;
    reg [15:0] next_count;
    always @(*) begin
        case (state)
            2'b00: begin next_s = s; next_state = 2'b01; next_count = 16'd1; end
            2'b01: begin next_s = s; next_state = (s > last_s) ? 2'b10 : 2'b01; next_count = (s > last_s) ? 16'd1 : count + 1; end
            2'b10: begin next_s = s; next_state = (s > last_s) ? 2'b11 : 2'b01; next_count = (s > last_s) ? 16'd1 : count + 1; end
            2'b11: begin next_s = s; next_state = (s > last_s) ? 2'b11 : 2'b00; next_count = (s > last_s) ? count + 1 : 16'd1; end
        endcase
    end
    always @(*) begin
        case (state)
            2'b00: begin fr0 = 1; fr1 = 1; fr2 = 1; dfr = 0; end
            2'b01: begin fr0 = 1; fr1 = 1; fr2 = 0; dfr = 0; end
            2'b10: begin fr0 = 1; fr1 = 0; fr2 = 0; dfr = 0; end
            2'b11: begin fr0 = 0; fr1 = 0; fr2 = 0; dfr = 1; end
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            count <= 16'd1;
            last_s <= 3'd0;
            fr0 <= 1;
            fr1 <= 1;
            fr2 <= 1;
            dfr <= 0;
        end else begin
            state <= next_state;
            count <= next_count;
            last_s <= s;
        end
    end
endmodule

