    reg [2:0] level;
    reg [2:0] level_next;
    reg [2:0] level_prev;
    reg [1:0] state;
    reg [1:0] state_next;
    wire [1:0] state_next_combined;
    wire [2:0] level_next_combined;
    reg [2:0] nominal_flow;
    reg [2:0] nominal_flow_next;
    reg [2:0] nominal_flow_prev;
    reg dfr_reg;
    reg fr2_reg;
    reg fr1_reg;
    reg fr0_reg;
    always @(*) begin
        level_next = level;
        state_next = state;
        nominal_flow_next = nominal_flow;
