                    state_next = 2'b01;
                    nominal_flow_next = 3'b001;
                end else if (s[0]) begin
                    state_next = 2'b10;
                    nominal_flow_next = 3'b001;
                end else begin
                    state_next = 2'b11;
                    nominal_flow_next = 3'b111;
                end
            end
            2'b01: begin
                if (s[2]) begin
                    state_next = 2'b00;
                end else if (s[1]) begin
                    state_next = 2'b01;
                end else begin
                    state_next = 2'b10;
                    nominal_flow_next = 3'b010;
                end
            end
            2'b10: begin
                if (s[2]) begin
                    state_next = 2'b00;
                end else begin
                    state_next = 2'b10;
                    nominal_flow_next = 3'b011;
