// State machine: the water level is determined by three sensors (s[2] is
// at the top, s[0] is at the bottom, and the water level is in between
// the two). The flow rate is determined by the nominal flow rate given
// in the table plus an additional flow rate controlled by the
// Supplemental flow valve (dfr), which is opened when the water level
// goes from below the lowest sensor to above the highest sensor.
module TopModule(
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);
    reg [1:0] state;
    reg [1:0] next_state;
    reg [2:0] level;
    reg [2:0] next_level;
    reg [1:0] delta;
    reg [1:0] next_delta;
    wire [1:0] level_enc = {(level == 2), (level == 1)};
    wire [1:0] next_level_enc = {(next_level == 2), (next_level == 1)};
    wire [1:0] delta_enc = {delta, ~delta};
    wire [2:0] fr;
    assign fr = (state == 2'b00) ? 3'b000 :
               (state == 2'b01) ? {1'b0, delta_enc[1], delta_enc[0]} :
               {1'b0, 1'b1, 1'b0};
    always @(*) begin
        case (level)
            0: begin next_level = 1; next_delta = 0; end
            1: begin next_level = 2; next_delta = 0; end
            2: begin next_level = 2; next_delta = 1; end
        endcase
    end
    always @(*) begin
        case (state)
            2'b00: next_state = 2'b01;
            2'b01: next_state = (level_enc == next_level_enc) ? 2'b01 : 2'b10;
            2'b10: next_state = (level_enc == next_level_enc) ? 2'b10 : 2'b11;
            2'b11: next_state = (level_enc == next_level_enc) ? 2'b11 : 2'b00;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin state <= 2'b00; level <= 0; delta <= 0; end
        else begin
            state <= next_state;
            level <= next_level;
            delta <= next_delta;
        end
    end
    always @(*) begin
        case (fr)
            3'b000: begin fr2 <= 1; fr1 <= 1; fr0 <= 1; end
            3'b001: begin fr2 <= 1; fr1 <= 1; fr0 <= 0; end
            3'b010: begin fr2 <= 1; fr1 <= 0; fr0 <= 1; end
            3'b011: begin fr2 <= 1; fr1 <= 0; fr0 <= 0; end
            3'b100: begin fr2 <= 0; fr1 <= 1; fr0 <= 1; end
            3'b101: begin fr2 <= 0; fr1 <= 1; fr0 <= 0; end
            3'b110: begin fr2 <= 0; fr1 <= 0; fr0 <= 1; end
            3'b111: begin fr2 <= 0; fr1 <= 0; fr0 <= 0; end
        endcase
        dfr <= (delta == 1);
    end
endmodule

