// Large reservior of water with three sensors: the flow rate changes
// depending on the water level and the level previous to the last sensor
// change, as described in the problem description.
module TopModule(input clk, input reset, input [2:0] s, output reg fr2,
                 output reg fr1, output reg fr0, output reg dfr);
  reg [2:0] level;
  reg [2:0] next_level;
  reg [2:0] prev_level;
  reg [2:0] prev_prev_level;
  reg [1:0] incr;
  always @(*) begin
    next_level = level;
    incr = 0;
    if (s[2]) begin
      next_level = 3'b111;
      fr0 = 1; fr1 = 1; fr2 = 1; dfr = 1;
    end else if (s[1]) begin
      next_level = 3'b011;
      fr0 = 1; fr1 = 1; fr2 = 0; dfr = 0;
    end else if (s[0]) begin
      next_level = 3'b001;
      fr0 = 1; fr1 = 0; fr2 = 0; dfr = 0;
    end else begin
      next_level = 3'b000;
      fr0 = 0; fr1 = 0; fr2 = 0; dfr = 1;
    end
    if (level < next_level) incr = 2'b01;
    if (prev_level < level && level < next_level) incr = 2'b10;
  end
  always @(posedge clk) begin
    if (reset) begin
      level <= 3'b000;
      prev_level <= 3'b000;
      prev_prev_level <= 3'b000;
    end else begin
      level <= next_level;
      prev_level <= level;
      prev_prev_level <= prev_level;
      case (incr)
        2'b01: begin fr0 <= 1; fr1 <= fr1; fr2 <= fr2; dfr <= dfr; end
        2'b10: begin fr0 <= 1; fr1 <= 1; fr2 <= fr2; dfr <= dfr; end
        2'b11: begin fr0 <= 1; fr1 <= 1; fr2 <= 1; dfr <= dfr; end
      endcase
    end
  end
endmodule

