// Large reservoir of water serves several users. In order to keep the level
// of water sufficiently high, three sensors are placed vertically at 5-inch
// intervals. When the water level is above the highest sensor s[2], the input
// flow rate should be zero. When the level is below the lowest sensor s[0],
// the flow rate should be at maximum (both Nominal flow valve and Supplemental
// flow valve opened). The flow rate when the level is between the upper and
// lower sensors is determined by two factors: the water level and the level
// previous to the last sensor change. Each water level has a nominal flow
// rate associated with it as show in the table below. If the sensor change
// indicates that the previous level was lower than the current level, the flow
// rate should be increased by opening the Supplemental flow valve (controlled
// by dfr).
module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);
    reg [1:0] state, next_state;
    wire [1:0] level;
    wire [1:0] next_level;
    reg [2:0] count;
    wire [2:0] next_count;
    wire open_nominal;
    wire open_supp;
    wire [2:0] nominal;
    wire [2:0] next_nominal;
    wire [2:0] fr;
    wire [2:0] next_fr;
    reg [2:0] prev_s;
    reg [2:0] prev_prev_s;

    // Determine the level based on the sensors.
    always @* begin
        case (s)
            3'b000: level = 2'b00;
            3'b001: level = 2'b01;
            3'b010: level = 2'b01;
            3'b011: level = 2'b10;
